// ═══════════════════════════════════════════════════════════
// 🧮 CALCULAR TODAS AS VARIÁVEIS DO TEMPLATE
// ═══════════════════════════════════════════════════════════

const metrics = $input.item.json;
const user = $('📦 Loop por Usuário').item.json;

// ─── Parse helpers ───
const parseArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  try { return JSON.parse(v); } catch { return []; }
};

const completed = parseInt(metrics.tasks_completed) || 0;
const created = parseInt(metrics.tasks_created) || 0;
const pending = parseInt(metrics.tasks_pending) || 0;
const overdue = parseInt(metrics.tasks_overdue) || 0;
const interactions = parseInt(metrics.interactions) || 0;
const total = completed + pending + overdue;

// ─── Percentuais ───
const pct = (n, d) => d > 0 ? Math.round((n / d) * 100) : 0;
const completion_pct = pct(completed, total);
const pct_completed = pct(completed, total);
const pct_pending = pct(pending, total);
const pct_overdue = pct(overdue, total);

// ─── Score message ───
let score_message;
if (completion_pct >= 90) score_message = 'Semana extraordinária! Você arrasou! 🏆';
else if (completion_pct >= 70) score_message = 'Semana forte! Você manteve o ritmo mesmo nos dias difíceis.';
else if (completion_pct >= 50) score_message = 'Metade feita é mais que zero. Cada passo conta!';
else if (completion_pct >= 30) score_message = 'Semana de resistência. O fato de estar aqui já mostra força.';
else score_message = 'Semana mais lenta, e tá tudo bem. O Desafoga tá aqui pra próxima.';

// ─── Datas formatadas ───
const formatBrDate = (d) => {
  const dt = new Date(d + 'T12:00:00');
  const day = String(dt.getDate()).padStart(2, '0');
  const months = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
  return `${day}/${months[dt.getMonth()]}`;
};
const week_start = formatBrDate(metrics.week_start);
const week_end = formatBrDate(metrics.week_end);

// ─── Categorias (Donut) ───
const categories = parseArr(metrics.categories);
const catColors = ['#6B3FA0', '#5EDBA5', '#FFD166', '#6EC6FF', '#FF7A6E', '#C9A8E8'];
const CIRC = 282.74;
const catTotal = categories.reduce((s, c) => s + parseInt(c.count), 0) || 1;

const catData = [];
let dashAcc = 0;
for (let i = 0; i < Math.min(categories.length, 5); i++) {
  const c = categories[i];
  const count = parseInt(c.count);
  const catPct = Math.round((count / catTotal) * 100);
  const dash = (catPct / 100) * CIRC;
  catData.push({
    name: c.name,
    count,
    pct: catPct,
    color: catColors[i],
    dash: dash.toFixed(2),
    offset: dashAcc > 0 ? `-${dashAcc.toFixed(2)}` : '0'
  });
  dashAcc += dash;
}

// Preencher até 5 slots (vazios não renderizam no donut)
while (catData.length < 5) {
  catData.push({ name: '-', count: 0, pct: 0, color: '#F3ECFA', dash: '0', offset: '0' });
}

// ─── Dia a dia ───
const dayByDay = parseArr(metrics.day_by_day);
const dayMap = {};
for (const d of dayByDay) {
  dayMap[parseInt(d.dow)] = parseInt(d.count);
}

const dayClass = (count) => {
  if (count >= 3) return 'great';
  if (count >= 1) return 'good';
  return 'none';
};

// ISODOW: 1=Seg ... 7=Dom
const days = [
  { key: 'mon', dow: 1 }, { key: 'tue', dow: 2 }, { key: 'wed', dow: 3 },
  { key: 'thu', dow: 4 }, { key: 'fri', dow: 5 }, { key: 'sat', dow: 6 },
  { key: 'sun', dow: 7 }
];

const dayData = {};
for (const d of days) {
  const count = dayMap[d.dow] || 0;
  dayData[`${d.key}_count`] = count;
  dayData[`${d.key}_class`] = dayClass(count);
}

// ─── Streak ───
const streakDates = parseArr(metrics.streak_dates)
  .map(d => d.substring(0, 10))
  .sort()
  .reverse();

let streak = 0;
if (streakDates.length > 0) {
  const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
  let checkDate = new Date(today);
  checkDate.setHours(12, 0, 0, 0);

  for (let i = 0; i < 60; i++) {
    const dateStr = checkDate.toISOString().substring(0, 10);
    if (streakDates.includes(dateStr)) {
      streak++;
    } else if (i > 0) {
      break; // gap found
    }
    checkDate.setDate(checkDate.getDate() - 1);
  }
}

let streak_message;
if (streak >= 14) streak_message = 'Fenômeno! 🏆';
else if (streak >= 7) streak_message = 'Uma semana inteira! 🔥';
else if (streak >= 3) streak_message = 'Tá criando ritmo!';
else if (streak >= 1) streak_message = 'Todo dia conta!';
else streak_message = 'Bora começar hoje!';

// ─── Destaques (gerados dinamicamente) ───
const highlights = [];

// Destaque 1: melhor dia
const bestDay = days.reduce((best, d) => {
  const cnt = dayMap[d.dow] || 0;
  return cnt > (best.count || 0) ? { key: d.key, dow: d.dow, count: cnt } : best;
}, { count: 0 });
const dayNames = { mon:'segunda', tue:'terça', wed:'quarta', thu:'quinta', fri:'sexta', sat:'sábado', sun:'domingo' };
if (bestDay.count > 0) {
  highlights.push(`Seu melhor dia foi <strong>${dayNames[bestDay.key]}</strong> com <strong>${bestDay.count} tarefa(s)</strong> concluída(s)!`);
} else {
  highlights.push('Semana de recomeço. Cada novo dia é uma chance nova!');
}

// Destaque 2: categoria top
if (categories.length > 0) {
  highlights.push(`Sua categoria mais ativa: <strong>${categories[0].name}</strong> com ${categories[0].count} tarefa(s). Tá focad${(user.gender || '').toLowerCase() === 'feminino' ? 'a' : 'o'}!`);
} else {
  highlights.push('Que tal explorar categorias diferentes essa semana?');
}

// Destaque 3: interações
if (interactions > 20) {
  highlights.push(`Você mandou <strong>${interactions} mensagens</strong> pro Desafoga essa semana. Parceria forte! 💬`);
} else if (interactions > 0) {
  highlights.push(`<strong>${interactions} interações</strong> essa semana. Cada mensagem é um passo. 💬`);
} else {
  highlights.push('Semana mais silenciosa. O Desafoga tá sempre aqui quando precisar. 💜');
}

// ─── Upcoming tasks ───
const upcoming = parseArr(metrics.upcoming_tasks);
const upcoming_note = upcoming.length > 0
  ? `Você tem ${upcoming.length} tarefa(s) já agendada(s). O Desafoga vai te lembrar de cada uma!`
  : 'Nenhuma tarefa agendada ainda. Bora planejar? É só me mandar!';

// ─── Histórias de superação (banco estático, n8n roda uma por semana) ───
const stories = [
  {
    name: 'Marina, 34',
    age: '34 anos',
    location: 'São Paulo',
    tag: 'Diagnosticada aos 29',
    text: '<p>Eu achava que esquecimento era preguiça. Perdi emprego, perdi prazos, perdi a confiança em mim mesma. Quando veio o diagnóstico de TDAH, chorei — mas de alívio.</p><p>O que mudou não foi uma pílula mágica. Foi aceitar que meu cérebro funciona diferente e criar sistemas que trabalham <em>a favor</em> dele. Hoje eu uso o Desafoga pra quebrar tudo em pedaços pequenos. E cada \"feito\" que aparece ali me prova que eu sou capaz.</p>',
    takeaway: 'Não é sobre fazer tudo. É sobre fazer do seu jeito — e reconhecer cada passo.'
  },
  {
    name: 'Rafael, 28',
    age: '28 anos',
    location: 'Belo Horizonte',
    tag: 'Diagnosticado aos 25',
    text: '<p>Eu era o cara que tinha mil ideias e não terminava nenhuma. Na faculdade, rodei duas vezes. No trabalho, vivia apagando incêndio. Achava que era falta de caráter.</p><p>O diagnóstico veio tarde, mas veio. Descobri que meu cérebro funciona por recompensas rápidas. Então comecei a fragmentar tudo: ao invés de \"estudar 3 horas\", eu coloco \"ler 2 páginas\". E funciona. Cada micro-conquista gera a próxima.</p>',
    takeaway: 'Fragmentar não é fazer menos. É fazer do tamanho que seu cérebro consegue abraçar.'
  },
  {
    name: 'Camila, 41',
    age: '41 anos',
    location: 'Curitiba',
    tag: 'Mãe de 2, diagnosticada aos 38',
    text: '<p>Ser mãe com TDAH é uma montanha-russa invisível. Eu esquecia reunião da escola, perdia prazo de matrícula, e a culpa me consumia. Achava que toda mãe dava conta — menos eu.</p><p>Quando fui diagnosticada, entendi que eu precisava de suporte, não de perfeição. O Desafoga virou meu segundo cérebro: ele lembra o que eu esqueço, e eu faço o que consigo. E está sendo o suficiente.</p>',
    takeaway: 'Pedir ajuda não é fraqueza. É a coisa mais inteligente que seu cérebro TDAH pode fazer.'
  },
  {
    name: 'Thiago, 31',
    age: '31 anos',
    location: 'Recife',
    tag: 'Empreendedor com TDAH',
    text: '<p>Abrir um negócio com TDAH é caótico e genial ao mesmo tempo. Eu tinha hiperfoco pra criar, mas zero consistência pra manter. Vivia largando projetos pela metade.</p><p>O que salvou foi sistematizar. Não preciso lembrar de tudo — preciso de um sistema que lembre por mim. Listas no Desafoga, lembretes no horário certo, e um check no final do dia. Simples assim. O difícil virou rotina.</p>',
    takeaway: 'Sistemas existem pra libertar o cérebro criativo, não pra prendê-lo.'
  },
  {
    name: 'Juliana, 36',
    age: '36 anos',
    location: 'Porto Alegre',
    tag: 'TDAH + superdotação',
    text: '<p>Eu sempre fui \"inteligente demais pra ter problema\". Notas boas, leitura rápida, conexões que ninguém fazia. Mas por dentro era um caos: 15 abas abertas na cabeça, ansiedade por não dar conta do que eu sabia que podia fazer.</p><p>Quando descobri que TDAH e superdotação coexistem, parei de me cobrar por um padrão neurotípico. Meu ritmo é irregular — e tá tudo bem. Nos dias bons eu voo, nos dias difíceis eu descanso. Os dois contam.</p>',
    takeaway: 'Seu potencial não some nos dias lentos. Ele só tá recarregando.'
  }
];

// ─── Dicas da semana (banco estático) ───
const tips = [
  {
    title: 'A regra dos 2 minutos',
    body: 'Se uma tarefa leva menos de 2 minutos, faça agora. Não anote, não adie. Só faça. Responder aquele e-mail, guardar a louça, mandar o pix. Seu cérebro TDAH adora a dopamina de riscar algo da lista.',
    cta: 'Teste hoje: faça 3 tarefas de 2min seguidas'
  },
  {
    title: 'Body doubling digital',
    body: 'Sabe quando é mais fácil trabalhar com alguém do lado? O Desafoga funciona como seu body double digital. Mande suas tarefas, peça pra ele te cobrar, e use os lembretes como companhia produtiva.',
    cta: 'Mande uma tarefa pro Desafoga agora'
  },
  {
    title: 'A técnica do \"só 5 minutos\"',
    body: 'Quando a procrastinação bater, faça um acordo com seu cérebro: \"Só 5 minutos, depois paro.\" Na maioria das vezes, o hiperfoco acende e você segue. O difícil é começar — e 5 minutos resolve isso.',
    cta: 'Escolha a tarefa mais temida e dê 5min'
  },
  {
    title: 'Categorize para priorizar',
    body: 'Cérebro TDAH odeia \"lista infinita\". Use categorias no Desafoga pra separar suas tarefas por contexto: Trabalho, Saúde, Casa. Quando olhar só uma categoria por vez, fica muito menos overwhelming.',
    cta: 'Revise suas categorias no Desafoga'
  },
  {
    title: 'O poder do \"feito imperfeito\"',
    body: 'Perfeccionismo é o maior inimigo do TDAH. Um e-mail enviado com 80% de qualidade é infinitamente melhor que um e-mail perfeito que nunca sai. Libere-se de fazer perfeito — faça feito.',
    cta: 'Identifique 1 tarefa travada pelo perfeccionismo'
  }
];

// Selecionar história e dica baseado na semana do ano
const weekOfYear = Math.ceil((new Date() - new Date(new Date().getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000));
const story = stories[weekOfYear % stories.length];
const tip = tips[weekOfYear % tips.length];

return [{
  json: {
    user_phone: user.user_phone,
    frist_name: user.frist_name,
    gender: user.gender,
    created_from: user.created_from,
    last_interaction_at: user.last_interaction_at,
    public_id: user.public_id,
    // Template vars
    week_start,
    week_end,
    completion_pct,
    score_message,
    tasks_completed: completed,
    tasks_created: created,
    tasks_pending: pending,
    tasks_overdue: overdue,
    tasks_total: total || catTotal,
    interactions,
    pct_completed,
    pct_pending,
    pct_overdue,
    catData,
    dayData,
    streak,
    streak_message,
    highlights,
    dopamine_quote: metrics.dopamine_quote || 'Seu jeito funciona.',
    upcoming,
    upcoming_note,
    story,
    tip
  }
}];

// ═══════════════════════════════════════════════════════════
// 📝 MONTAR O HTML FINAL DO RELATÓRIO SEMANAL v2
// ═══════════════════════════════════════════════════════════

const d = $input.item.json;

// Helper: gerar upcoming tasks HTML
const upcomingHtml = d.upcoming.length > 0
  ? d.upcoming.map(t => {
      const dt = new Date(t.due_date + 'T12:00:00');
      const dayNames = ['dom','seg','ter','qua','qui','sex','sáb'];
      const months = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
      const formatted = `${dayNames[dt.getDay()]} ${dt.getDate()}/${months[dt.getMonth()]}`;
      return `<li class="next-week-item"><span class="next-week-dot"></span><span>${t.title} · <strong>${formatted}</strong></span></li>`;
    }).join('\n        ')
  : '<li class="next-week-item"><span class="next-week-dot"></span><span>Nenhuma tarefa agendada ainda</span></li>';

// Helper: gerar donut circles
const donutCircles = d.catData
  .filter(c => parseFloat(c.dash) > 0)
  .map(c => `<circle class="cat-donut-ring" cx="60" cy="60" r="45" stroke="${c.color}" stroke-dasharray="${c.dash} 282.74" stroke-dashoffset="${c.offset}" />`)
  .join('\n            ');

// Helper: gerar legend items
const legendItems = d.catData
  .filter(c => c.count > 0)
  .map(c => `<div class="cat-legend-item">
            <div class="cat-legend-dot" style="background: ${c.color}"></div>
            <span class="cat-legend-name">${c.name}</span>
            <span class="cat-legend-count">${c.count}</span>
            <span class="cat-legend-pct">${c.pct}%</span>
          </div>`)
  .join('\n          ');

const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
