.cat-legend-count{font-family:'Fraunces',serif;font-size:14px;font-weight:700;color:var(--text-dark)}
.cat-legend-pct{font-size:11px;color:var(--text-soft);min-width:32px;text-align:right}
.day-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;text-align:center}
.day-col-label{font-size:10px;font-weight:600;color:var(--text-soft);text-transform:uppercase;letter-spacing:.3px;margin-bottom:6px}
.day-bubble{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:'Fraunces',serif;font-size:14px;font-weight:600;margin:0 auto}
.day-bubble.great{background:var(--accent-mint);color:#1A5C3A}.day-bubble.good{background:#C8F0D8;color:#2A6E4A}.day-bubble.ok{background:var(--accent-gold);color:#7A6520}.day-bubble.low{background:#FFE0DD;color:#8B3A33}.day-bubble.none{background:var(--purple-wash);color:var(--text-soft)}
.highlight-item{display:flex;align-items:flex-start;gap:12px;padding:12px 0}
.highlight-item+.highlight-item{border-top:1px solid var(--purple-wash)}
.highlight-emoji{font-size:20px;flex-shrink:0;margin-top:2px}
.highlight-text{font-size:14px;color:var(--text-mid);line-height:1.5}
.highlight-text strong{color:var(--text-dark);font-weight:600}
.streak-banner{background:linear-gradient(135deg,var(--purple-wash) 0%,var(--purple-glow) 100%);border-radius:var(--radius-sm);padding:16px;display:flex;align-items:center;gap:14px;margin-top:4px}
.streak-fire{font-size:32px;animation:pulse 2s ease-in-out infinite}
.streak-count{font-family:'Fraunces',serif;font-size:22px;font-weight:700;color:var(--purple-deep);line-height:1.1}
.streak-desc{font-size:12px;color:var(--text-mid);font-weight:500}
.story-card{margin:16px 20px;border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm);animation:fadeSlideUp .6s ease-out both;background:var(--white)}
.story-header{background:linear-gradient(135deg,#FFF0F5 0%,#F9E8F0 100%);padding:16px 20px;display:flex;align-items:center;gap:10px}
.story-header-icon{width:36px;height:36px;border-radius:10px;background:rgba(107,63,160,0.1);display:flex;align-items:center;justify-content:center;font-size:18px}
.story-header-title{font-family:'Fraunces',serif;font-size:17px;font-weight:600;color:var(--text-dark)}
.story-body{padding:20px}
.story-name{font-family:'Fraunces',serif;font-size:16px;font-weight:600;color:var(--purple-main);margin-bottom:4px}
.story-meta{font-size:12px;color:var(--text-soft);font-weight:500;margin-bottom:12px;display:flex;align-items:center;gap:6px}
.story-meta-dot{width:4px;height:4px;border-radius:50%;background:var(--text-soft)}
.story-text{font-size:14px;color:var(--text-mid);line-height:1.7}
.story-text p+p{margin-top:10px}
.story-takeaway{margin-top:16px;padding:14px 16px;background:var(--purple-wash);border-radius:var(--radius-xs);border-left:3px solid var(--purple-main)}
.story-takeaway-label{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.5px;color:var(--purple-main);margin-bottom:4px}
.story-takeaway-text{font-size:13px;color:var(--text-mid);font-style:italic;line-height:1.5}
.tip-card{margin:16px 20px;background:linear-gradient(145deg,#E6FAF5 0%,#D4F5EC 50%,#E8FBF1 100%);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm);animation:fadeSlideUp .6s ease-out both;position:relative}
.tip-card::before{content:'';position:absolute;top:-20px;right:-20px;width:80px;height:80px;border-radius:50%;background:rgba(94,219,165,0.15)}
.tip-header{padding:18px 20px 0;display:flex;align-items:center;gap:10px;position:relative;z-index:1}
.tip-icon{width:36px;height:36px;border-radius:10px;background:rgba(94,219,165,0.25);display:flex;align-items:center;justify-content:center;font-size:18px}
.tip-title-text{font-family:'Fraunces',serif;font-size:17px;font-weight:600;color:var(--text-dark)}
.tip-body{padding:14px 20px 20px;position:relative;z-index:1}
.tip-headline{font-family:'Fraunces',serif;font-size:15px;font-weight:600;color:var(--purple-deep);margin-bottom:8px}
.tip-text{font-size:14px;color:var(--text-mid);line-height:1.6}
.tip-try{margin-top:14px;display:inline-flex;align-items:center;gap:6px;background:var(--white);padding:8px 14px;border-radius:20px;font-size:12px;font-weight:600;color:var(--purple-main);box-shadow:0 2px 6px rgba(94,219,165,0.2)}
.dopamine-card{margin:16px 20px;background:linear-gradient(145deg,var(--purple-deep) 0%,var(--purple-main) 100%);border-radius:var(--radius);padding:28px 24px;text-align:center;color:var(--white);position:relative;overflow:hidden;box-shadow:var(--shadow-glow);animation:fadeSlideUp .6s ease-out both}
.dopamine-card::before{content:'';position:absolute;top:-30px;right:-30px;width:100px;height:100px;border-radius:50%;background:rgba(255,255,255,0.05)}
.dopamine-quote{font-family:'Fraunces',serif;font-size:18px;font-weight:400;font-style:italic;line-height:1.5;margin-bottom:10px;position:relative;z-index:1}
.dopamine-author{font-size:12px;opacity:0.7;font-weight:500;letter-spacing:.5px}
.next-week-list{list-style:none}
.next-week-item{display:flex;align-items:center;gap:10px;padding:10px 0;font-size:14px;color:var(--text-mid)}
.next-week-item+.next-week-item{border-top:1px solid var(--purple-wash)}
.next-week-dot{width:8px;height:8px;border-radius:50%;background:var(--purple-mid);flex-shrink:0}
.footer{text-align:center;padding:28px 20px 12px;animation:fadeSlideUp .5s ease-out .8s both}
.footer-brand{font-family:'Fraunces',serif;font-size:15px;font-weight:600;color:var(--purple-main);margin-bottom:2px}
.footer-tagline{font-size:12px;color:var(--text-soft);font-style:italic}
.footer-divider{width:40px;height:3px;border-radius:2px;background:var(--purple-light);margin:14px auto 0}
@keyframes fadeSlideDown{from{opacity:0;transform:translateY(-12px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeSlideUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeScaleUp{from{opacity:0;transform:scale(.92)}to{opacity:1;transform:scale(1)}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.1)}}
.legend{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
.legend-item{display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text-soft)}
.legend-dot{width:10px;height:10px;border-radius:50%}
.legend-dot.great{background:var(--accent-mint)}.legend-dot.ok{background:var(--accent-gold)}.legend-dot.low{background:#FFE0DD}.legend-dot.none{background:var(--purple-wash)}
</style>
</head>
<body>
<div class="report">
  <header class="hero">
    <div class="hero-badge">🧠 Raio-X Semanal</div>
    <h1 class="hero-greeting">E aí, ${d.frist_name}!</h1>
    <p class="hero-period">Semana de ${d.week_start} a ${d.week_end}</p>
  </header>

  <div class="score-section">
    <div class="score-card">
      <div class="score-ring-container">
        <svg viewBox="0 0 120 120" width="130" height="130">
          <defs><linearGradient id="scoreGradient" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#6B3FA0" /><stop offset="100%" stop-color="#5EDBA5" /></linearGradient></defs>
          <circle class="score-ring-bg" cx="60" cy="60" r="55" />
          <circle class="score-ring-fill" cx="60" cy="60" r="55" style="--score: ${d.completion_pct}" />
        </svg>
        <div class="score-value">
          <div class="score-number">${d.completion_pct}<span>%</span></div>
          <div class="score-label">concluídas</div>
        </div>
      </div>
      <p class="score-message">${d.score_message}</p>
    </div>
  </div>

  <div class="stats-strip">
    <div class="stat-item"><div class="stat-icon">✅</div><div class="stat-value">${d.tasks_completed}</div><div class="stat-label">Feitas</div></div>
    <div class="stat-item"><div class="stat-icon">📝</div><div class="stat-value">${d.tasks_created}</div><div class="stat-label">Criadas</div></div>
    <div class="stat-item"><div class="stat-icon">💬</div><div class="stat-value">${d.interactions}</div><div class="stat-label">Interações</div></div>
  </div>

  <div class="section">
    <div class="section-header"><div class="section-icon purple">📊</div><h2 class="section-title">Suas Tarefas</h2></div>
    <div class="section-body">
      <div class="task-bar-row"><span class="task-bar-label">Concluídas</span><div class="task-bar-track"><div class="task-bar-fill completed" style="width:${d.pct_completed}%"></div></div><span class="task-bar-count completed">${d.tasks_completed}</span></div>
      <div class="task-bar-row"><span class="task-bar-label">Pendentes</span><div class="task-bar-track"><div class="task-bar-fill pending" style="width:${d.pct_pending}%"></div></div><span class="task-bar-count pending">${d.tasks_pending}</span></div>
      <div class="task-bar-row"><span class="task-bar-label">Atrasadas</span><div class="task-bar-track"><div class="task-bar-fill overdue" style="width:${d.pct_overdue}%"></div></div><span class="task-bar-count overdue">${d.tasks_overdue}</span></div>
    </div>
  </div>

  <div class="section">
    <div class="section-header"><div class="section-icon teal">🏷️</div><h2 class="section-title">Por Categoria</h2></div>
    <div class="section-body">
      <div class="cat-layout">
        <div class="cat-donut-wrap">
          <svg viewBox="0 0 120 120" width="120" height="120">
            <circle cx="60" cy="60" r="45" fill="none" stroke="#F3ECFA" stroke-width="14" />
            ${donutCircles}
          </svg>
          <div class="cat-donut-center">
            <div class="cat-donut-total">${d.tasks_total}</div>
            <div class="cat-donut-label">tarefas</div>
          </div>
        </div>
        <div class="cat-legend">
          ${legendItems}
        </div>
      </div>
    </div>
  </div>

  <div class="section">
    <div class="section-header"><div class="section-icon mint">📅</div><h2 class="section-title">Dia a Dia</h2></div>
    <div class="section-body">
      <div class="day-grid">
        <div><div class="day-col-label">Seg</div><div class="day-bubble ${d.dayData.mon_class}">${d.dayData.mon_count}</div></div>
        <div><div class="day-col-label">Ter</div><div class="day-bubble ${d.dayData.tue_class}">${d.dayData.tue_count}</div></div>
        <div><div class="day-col-label">Qua</div><div class="day-bubble ${d.dayData.wed_class}">${d.dayData.wed_count}</div></div>
        <div><div class="day-col-label">Qui</div><div class="day-bubble ${d.dayData.thu_class}">${d.dayData.thu_count}</div></div>
        <div><div class="day-col-label">Sex</div><div class="day-bubble ${d.dayData.fri_class}">${d.dayData.fri_count}</div></div>
        <div><div class="day-col-label">Sáb</div><div class="day-bubble ${d.dayData.sat_class}">${d.dayData.sat_count}</div></div>
        <div><div class="day-col-label">Dom</div><div class="day-bubble ${d.dayData.sun_class}">${d.dayData.sun_count}</div></div>
      </div>
      <div class="legend">
        <div class="legend-item"><div class="legend-dot great"></div> 3+</div>
        <div class="legend-item"><div class="legend-dot ok"></div> 1–2</div>
        <div class="legend-item"><div class="legend-dot low"></div> atrasada</div>
        <div class="legend-item"><div class="legend-dot none"></div> sem ação</div>
      </div>
    </div>
  </div>

  <div class="section">
    <div class="section-header"><div class="section-icon gold">⭐</div><h2 class="section-title">Destaques</h2></div>
    <div class="section-body">
      <div class="highlight-item"><span class="highlight-emoji">🏆</span><span class="highlight-text">${d.highlights[0]}</span></div>
      <div class="highlight-item"><span class="highlight-emoji">💡</span><span class="highlight-text">${d.highlights[1]}</span></div>
      <div class="highlight-item"><span class="highlight-emoji">🔎</span><span class="highlight-text">${d.highlights[2]}</span></div>
    </div>
  </div>

  <div class="section">
    <div class="section-header"><div class="section-icon coral">🔥</div><h2 class="section-title">Consistência</h2></div>
    <div class="section-body">
      <div class="streak-banner">
        <div class="streak-fire">🔥</div>
        <div class="streak-info">
          <div class="streak-count">${d.streak} dias seguidos</div>
          <div class="streak-desc">usando o Desafoga · ${d.streak_message}</div>
        </div>
      </div>
    </div>
  </div>

  <div class="story-card">
    <div class="story-header"><div class="story-header-icon">💜</div><h2 class="story-header-title">História de Superação</h2></div>
    <div class="story-body">
      <div class="story-name">${d.story.name}</div>
      <div class="story-meta"><span>${d.story.location}</span><span class="story-meta-dot"></span><span>${d.story.tag}</span></div>
      <div class="story-text">${d.story.text}</div>
      <div class="story-takeaway">
        <div class="story-takeaway-label">O que fica</div>
        <div class="story-takeaway-text">${d.story.takeaway}</div>
      </div>
    </div>
  </div>

  <div class="tip-card">
    <div class="tip-header"><div class="tip-icon">🧩</div><span class="tip-title-text">Dica da Semana</span></div>
    <div class="tip-body">
      <div class="tip-headline">${d.tip.title}</div>
      <div class="tip-text">${d.tip.body}</div>
      <div class="tip-try">▶ ${d.tip.cta}</div>
    </div>
  </div>

  <div class="dopamine-card">
    <p class="dopamine-quote">&ldquo;${d.dopamine_quote}&rdquo;</p>
    <span class="dopamine-author">Desafoga pra você</span>
  </div>

  <div class="section">
    <div class="section-header"><div class="section-icon sky">🚀</div><h2 class="section-title">Semana que Vem</h2></div>
    <div class="section-body">
      <ul class="next-week-list">
        ${upcomingHtml}
      </ul>
      <p style="font-size:13px;color:var(--text-soft);margin-top:12px;font-style:italic;">${d.upcoming_note}</p>
    </div>
  </div>

  <div class="footer">
    <div class="footer-brand">Desafoga TDAH</div>
    <div class="footer-tagline">Seu Jeito Funciona.</div>
    <div class="footer-divider"></div>
  </div>
</div>
</body>
</html>`;

// Gerar também um resumo texto para WhatsApp
const suf = (d.gender || '').toLowerCase() === 'feminino' ? 'a' : 'o';
const textSummary = `🧠 *Raio-X Semanal | ${d.week_start} a ${d.week_end}*\n\nE aí, ${d.frist_name}! Seu relatório da semana tá pronto 💜\n\n✅ *${d.tasks_completed}* tarefas concluídas (${d.completion_pct}%)\n📝 *${d.tasks_created}* criadas\n💬 *${d.interactions}* interações\n🔥 *${d.streak}* dias de streak\n\n${d.score_message}\n\n👆 Abre o link pra ver seu relatório completo com gráficos!`;

return [{
  json: {
    ...d,
    html_report: html,
    text_summary: textSummary
  }
}];
